104:         var started=process.orElseThrow().info().startInstant();
105:         return started.isEmpty() || started.orElseThrow().truncatedTo(ChronoUnit.MICROS)
106:                 .equals(owner.processStartedAt().truncatedTo(ChronoUnit.MICROS));
