 22: @Repository
 23: public class JdbcJ3CollectionStore implements J3CollectionStore {
 24:     private static final JsonMapper JSON = JsonMapper.builder().build();
 25:     private final NamedParameterJdbcTemplate jdbc;
 26:     public JdbcJ3CollectionStore(NamedParameterJdbcTemplate jdbc) { this.jdbc = jdbc; }
 27: 
 28:     @Override @Transactional
 29:     public void begin(UUID id, LocalDate date, Trigger trigger, Instant startedAt) {
 30:         var p = params(id).addValue("date", date).addValue("trigger", trigger.name()).addValue("start", ts(startedAt));
 31:         jdbc.update("""
 32:                 insert into j3_collection_run(run_id,collection_date,trigger_kind,started_at,state)
 33:                 values (:id,:date,:trigger,:start,'RUNNING') on conflict (run_id) do nothing
 34:                 """, p);
 35:         Integer matches = jdbc.queryForObject("""
 36:                 select count(*) from j3_collection_run where run_id=:id and collection_date=:date
 37:                 and trigger_kind=:trigger and started_at=:start
 38:                 """, p, Integer.class);
 39:         if (matches == null || matches != 1) throw new IllegalStateException("J3_RUN_IDENTITY_CONFLICT");
 40:     }
 41: 
 42:     @Override @Transactional
 43:     public void appendPage(UUID id, J3MinimizedPageEvidence page) {
 44:         var p = params(id).addValue("page", page.page()).addValue("snapshot", page.snapshotId())
 45:                 .addValue("json", JSON.writeValueAsString(page));
 46:         // The run lock serializes append against terminal publication and duplicate completion.
 47:         jdbc.queryForObject("select run_id from j3_collection_run where run_id=:id for update", p, UUID.class);
 48:         List<Boolean> existing = jdbc.query("""
 49:                 select evidence=cast(:json as jsonb) from j3_collection_page where run_id=:id and page=:page
 50:                 """, p, (rs, n) -> rs.getBoolean(1));
 51:         if (!existing.isEmpty()) {
 52:             if (!existing.getFirst()) throw new IllegalStateException("J3_PAGE_IDENTITY_CONFLICT");
 53:             return;
 54:         }
 55:         jdbc.update("""
 56:                 insert into j3_collection_page(run_id,page,snapshot_id,evidence)
 57:                 values (:id,:page,:snapshot,cast(:json as jsonb))
 58:                 """, p);
 59:     }
